    .reg .u32 %r<80>;
    .reg .u64 %rd<50>;
    .reg .f32 %f<20>;
    .reg .pred %p<12>;
    .shared .align 4 .f32 smA[256];
    .shared .align 4 .f32 smB[256];
    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r1, [M];
    ld.param.u32 %r2, [N];
    ld.param.u32 %r3, [K];
    ld.param.u32 %r4, [K_chunk];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    // thread indices
    mov.u32 %r5, %tid.y;
    mov.u32 %r6, %tid.x;
    mov.u32 %r7, %ctaid.y;
    mov.u32 %r8, %ctaid.x;
    mov.u32 %r9, %ctaid.z;
    // row, col
    mov.u32 %r10, %ntid.y;
    mad.lo.u32 %r11, %r7, %r10, %r5;
    mov.u32 %r12, %ntid.x;
    mad.lo.u32 %r13, %r8, %r12, %r6;
    // split-K range
    mul.lo.u32 %r14, %r9, %r4;
    add.u32 %r15, %r14, %r4;
    setp.gt.u32 %p1, %r15, %r3;
    selp.b32 %r16, %r3, %r15, %p1;
    // validity predicates (row/col within output bounds)
    setp.lt.u32 %p2, %r11, %r1;
    setp.lt.u32 %p3, %r13, %r2;
    // shared-memory store addresses for this thread
    mad.lo.u32 %r17, %r5, 16, %r6;
    shl.b32 %r18, %r17, 2;
    mov.u32 %r19, smA;
    add.u32 %r20, %r19, %r18;
    mov.u32 %r21, smB;
    add.u32 %r22, %r21, %r18;
