    cvt.u64.u32 %rd4, %r11;
    cvt.u64.u32 %rd5, %r3;
    mul.lo.u64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.u64 %rd8, %rd1, %rd7;
    // B col base pointer = B_ptr + col*4
    cvt.u64.u32 %rd9, %r13;
    shl.b64 %rd10, %rd9, 2;
    add.u64 %rd11, %rd2, %rd10;
    // N stride in bytes
    cvt.u64.u32 %rd12, %r2;
    shl.b64 %rd13, %rd12, 2;
    mov.f32 %f1, 0f00000000;
    mov.u32 %r23, %r14;
