    add.u32 %r24, %r23, %r6;
    setp.lt.u32 %p5, %r24, %r16;
    and.pred %p6, %p2, %p5;
    cvt.u64.u32 %rd14, %r24;
    shl.b64 %rd15, %rd14, 2;
    add.u64 %rd16, %rd8, %rd15;
    @%p6 ld.global.f32 %f2, [%rd16];
    @!%p6 mov.f32 %f2, 0f00000000;
    st.shared.f32 [%r20], %f2;
    add.u32 %r25, %r23, %r5;
    setp.lt.u32 %p7, %r25, %r16;
    and.pred %p8, %p3, %p7;
    cvt.u64.u32 %rd17, %r25;
    mul.lo.u64 %rd18, %rd17, %rd13;
    add.u64 %rd19, %rd11, %rd18;
    @%p8 ld.global.f32 %f3, [%rd19];
    @!%p8 mov.f32 %f3, 0f00000000;
    st.shared.f32 [%r22], %f3;
